import { definePipeline, defineStream, HttpError, IngestConfigError, rawRows, rawTable, timestampWindow, type ErrorClassifier, type FetchContext, type TimestampRange } from '@chkit/plugin-ingest'

const database = 'default'
// Keep stream IDs and destinations tied to one Linear workspace; use new ones when switching accounts.
const query = `query Issues($after: String, $from: DateTimeOrDuration!, $to: DateTimeOrDuration!) {
  issues(first: 100, after: $after, includeArchived: true, orderBy: updatedAt,
    filter: { updatedAt: { gte: $from, lte: $to } }) {
    nodes { id identifier title description url createdAt updatedAt archivedAt completedAt canceledAt
      team { id key name } state { name type } assignee { id name email }
      comments(first: 20, includeArchived: true) { nodes { id body createdAt updatedAt } pageInfo { hasNextPage endCursor } }
    }
    pageInfo { hasNextPage endCursor }
  }
}`
const commentsQuery = `query IssueComments($id: String!, $after: String) {
  issue(id: $id) { comments(first: 100, after: $after, includeArchived: true) {
    nodes { id body createdAt updatedAt } pageInfo { hasNextPage endCursor }
  } }
}`
interface Connection<T> { nodes: T[]; pageInfo: { hasNextPage: boolean; endCursor: string | null } }
interface Issue { id: string; updatedAt: string; comments: Connection<Record<string, unknown>>; [key: string]: unknown }
interface ResponseBody { data?: { issues: Connection<Issue> }; errors?: { message: string }[] }
interface CommentsBody { data?: { issue: { comments: Connection<Record<string, unknown>> } | null }; errors?: { message: string }[] }

export const linear_issuesRaw = rawTable({ database, name: 'linear_issues_raw' })

export const linearPipeline = definePipeline({
  id: 'linear', tags: ['provider:linear'], maxStreams: 1, maxFetches: 1,
  streams: [defineStream({
    id: 'linear.issues', tags: ['resource:issues'], destination: linear_issuesRaw,
    // Newest-first pages cannot advance a safe watermark until the whole window loads.
    incremental: timestampWindow({ start: new Date(0), overlapMs: 5 * 60 * 1000 }),
    classifyError: classifyLinearError,
    async *read(context) {
      let after: string | null = null
      const seen = new Set<string>()
      while (true) {
        const issues = await readPage(context, after, context.selection)
        for (const issue of issues.nodes) {
          if (!issue.id || !Number.isFinite(Date.parse(issue.updatedAt))) throw new IngestConfigError('Linear issue has no ID or valid updatedAt.')
          const comments = await completeComments(context, issue)
          yield { rows: rawRows([{ ...issue, comments }], (item) => item.id) }
        }
        if (!issues.pageInfo.hasNextPage) return
        after = continuation(issues.pageInfo.endCursor, seen, 'issue')
      }
    },
  })],
})

/** Linear reports GraphQL rate exhaustion as HTTP 400 rather than 429. */
function classifyLinearError(cause: unknown): ReturnType<ErrorClassifier> {
  if (!(cause instanceof HttpError) || cause.status !== 400 || !/"code"\s*:\s*"RATELIMITED"/.test(cause.body)) return undefined
  const headers = cause.response.headers
  const resets = ['requests', 'endpoint-requests', 'complexity'].flatMap((kind) => {
    if (headers.get(`x-ratelimit-${kind}-remaining`) !== '0') return []
    const reset = Number(headers.get(`x-ratelimit-${kind}-reset`))
    return Number.isFinite(reset) && reset > 0 ? [Math.max(0, reset - Date.now())] : []
  })
  return { kind: 'rate_limited', retryAfterMs: cause.retryAfterMs ?? (resets.length ? Math.max(...resets) : undefined) }
}

async function readPage(context: FetchContext, after: string | null, window: TimestampRange): Promise<Connection<Issue>> {
  const body = await graphql<ResponseBody>(context, query, { after, from: window.from.toISOString(), to: window.to.toISOString() }, 'issues')
  if (body.errors?.length || !body.data?.issues) throw new IngestConfigError(`Linear query failed: ${body.errors?.map((item) => item.message).join('; ') ?? 'missing issues'}`)
  return validateConnection(body.data.issues)
}

async function completeComments(context: FetchContext, issue: Issue): Promise<Connection<Record<string, unknown>>> {
  let page = validateConnection(issue.comments)
  const nodes = [...page.nodes]
  const seen = new Set<string>()
  while (page.pageInfo.hasNextPage) {
    const after = continuation(page.pageInfo.endCursor, seen, 'comment')
    const body = await graphql<CommentsBody>(context, commentsQuery, { id: issue.id, after }, 'issue comments')
    if (body.errors?.length || !body.data?.issue) throw new IngestConfigError('Linear comment query failed; the issue window is incomplete.')
    page = validateConnection(body.data.issue.comments)
    nodes.push(...page.nodes)
  }
  // Preserve the provider connection shape, with the terminal continuation information.
  return { ...issue.comments, nodes, pageInfo: page.pageInfo }
}

async function graphql<T>(context: FetchContext, document: string, variables: Record<string, unknown>, label: string): Promise<T> {
  return context.attempt(async (signal) => {
    const token = process.env.LINEAR_API_KEY?.trim()
    if (!token) throw new IngestConfigError('Set LINEAR_API_KEY.')
    const response = await fetch('https://api.linear.app/graphql', {
      method: 'POST', signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), redirect: 'error',
      headers: { Authorization: token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ query: document, variables }),
    })
    if (!response.ok) throw await HttpError.fromResponse(response)
    return await response.json() as T
  }, { label: `POST /graphql ${label}` })
}

function continuation(cursor: string | null, seen: Set<string>, resource: string): string {
  if (typeof cursor !== 'string' || !cursor.trim() || seen.has(cursor)) throw new IngestConfigError(`Linear returned no new ${resource} cursor.`)
  seen.add(cursor)
  return cursor
}

function validateConnection<T>(value: Connection<T>): Connection<T> {
  if (!value || !Array.isArray(value.nodes) || !value.pageInfo || typeof value.pageInfo.hasNextPage !== 'boolean') {
    throw new IngestConfigError('Linear returned an invalid connection.')
  }
  return value
}

import { afterEach, expect, test } from 'bun:test'
import { IngestConfigError, runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { linearPipeline } from '../index.js'

const originalFetch = globalThis.fetch
const originalToken = process.env.LINEAR_API_KEY
const cutoff = new Date('2026-01-02T00:00:00Z')
const emptyComments = { nodes: [], pageInfo: { hasNextPage: false, endCursor: null } }

function setFetch(handler: (...args: Parameters<typeof fetch>) => Promise<Response>): void {
  globalThis.fetch = Object.assign(handler, { preconnect: originalFetch.preconnect })
  process.env.LINEAR_API_KEY = 'fixture'
}

function selected() {
  return selectStreams([linearPipeline], []).map((item) => ({ ...item, stream: { ...item.stream, batchSize: 1, retry: { retries: 0 } } }))
}

afterEach(() => {
  globalThis.fetch = originalFetch
  if (originalToken === undefined) delete process.env.LINEAR_API_KEY
  else process.env.LINEAR_API_KEY = originalToken
})

test.serial('Linear filters bounded archived issues and completes comment and issue connections', async () => {
  const requests: { query: string; variables: Record<string, unknown> }[] = []
  setFetch(async (_input, init) => {
    const body = JSON.parse(String(init?.body))
    requests.push(body)
    if (body.query.includes('query IssueComments')) return Response.json({ data: { issue: { comments: {
      nodes: [{ id: 'c2', body: 'continued', custom: true }], pageInfo: { hasNextPage: false, endCursor: 'comments-done' },
    } } } })
    if (body.variables.after) return Response.json({ data: { issues: {
      nodes: [{ id: 'b', updatedAt: '2026-01-01T00:00:00Z', comments: emptyComments }], pageInfo: { hasNextPage: false, endCursor: 'done' },
    } } })
    return Response.json({ data: { issues: {
      nodes: [{ id: 'a', updatedAt: '2026-01-01T00:00:00Z', archivedAt: '2026-01-01T00:00:00Z', comments: {
        nodes: [{ id: 'c1', body: 'first' }], pageInfo: { hasNextPage: true, endCursor: 'comments-next' },
      } }], pageInfo: { hasNextPage: true, endCursor: 'issues-next' },
    } } })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const result = await runIngestion({ selected: selected(), backfill: undefined }, { journal, destination, now: () => cutoff })
  expect(result.ok).toBe(true)
  expect(requests[0]?.query).toContain('includeArchived: true')
  expect(requests[0]?.query).toContain('gte: $from, lte: $to')
  expect(requests[0]?.variables).toEqual({ after: null, from: '1970-01-01T00:00:00.000Z', to: cutoff.toISOString() })
  expect(requests[1]?.variables).toEqual({ id: 'a', after: 'comments-next' })
  expect(requests[2]?.variables.after).toBe('issues-next')
  const rows = destination.tables.get('default.linear_issues_raw') ?? []
  expect(rows.map((row) => row.id)).toEqual(['a', 'b'])
  expect(rows[0]?.raw).toMatchObject({ archivedAt: '2026-01-01T00:00:00Z', comments: { nodes: [{ id: 'c1' }, { id: 'c2', custom: true }], pageInfo: { hasNextPage: false } } })
  expect((await journal.readCheckpoint('linear.issues')).envelope?.state).toEqual({ watermark: cutoff.toISOString() })
})

test.serial('Linear comment failures leave the window uncommitted and replay from the beginning', async () => {
  let fail = true
  const starts: unknown[] = []
  setFetch(async (_input, init) => {
    const body = JSON.parse(String(init?.body))
    if (body.query.includes('query IssueComments')) {
      return fail ? Response.json({ errors: [{ message: 'unavailable' }] }) : Response.json({ data: { issue: { comments: emptyComments } } })
    }
    starts.push(body.variables.after)
    return Response.json({ data: { issues: {
      nodes: [{ id: 'a', updatedAt: '2026-01-01T00:00:00Z', comments: { nodes: [], pageInfo: { hasNextPage: true, endCursor: 'next' } } }],
      pageInfo: { hasNextPage: false, endCursor: null },
    } } })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(false)
  expect((await journal.readCheckpoint('linear.issues')).envelope).toBeUndefined()
  expect(destination.tables.size).toBe(0)
  fail = false
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(starts).toEqual([null, null])
})

test.serial('Linear destination failure does not save a timestamp watermark', async () => {
  setFetch(async () => Response.json({ data: { issues: { nodes: [{ id: 'a', updatedAt: '2026-01-01T00:00:00Z', comments: emptyComments }], pageInfo: { hasNextPage: false, endCursor: null } } } }))
  const journal = createMemoryJournal()
  const result = await runIngestion({ selected: selected(), backfill: undefined }, {
    journal, destination: { insert: async () => { throw new IngestConfigError('sink rejected') } }, now: () => cutoff,
  })
  expect(result.ok).toBe(false)
  expect((await journal.readCheckpoint('linear.issues')).envelope).toBeUndefined()
})

test.serial('Linear empty windows commit and subsequent runs overlap their cutoff', async () => {
  const starts: unknown[] = []
  setFetch(async (_input, init) => {
    starts.push(JSON.parse(String(init?.body)).variables.from)
    return Response.json({ data: { issues: { nodes: [], pageInfo: { hasNextPage: false, endCursor: null } } } })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-03T00:00:00Z') })).ok).toBe(true)
  expect(starts).toEqual(['1970-01-01T00:00:00.000Z', '2026-01-01T23:55:00.000Z'])
})

test.serial('Linear retries documented GraphQL HTTP 400 rate-limit errors', async () => {
  let attempts = 0
  setFetch(async () => {
    attempts++
    if (attempts === 1) return Response.json({ errors: [{ message: 'rate limit', extensions: { code: 'RATELIMITED' } }] }, { status: 400 })
    return Response.json({ data: { issues: { nodes: [], pageInfo: { hasNextPage: false, endCursor: null } } } })
  })
  const selected = selectStreams([linearPipeline], []).map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 1, minTimeout: 0, maxTimeout: 0 } } }))
  const journal = createMemoryJournal()
  const result = await runIngestion({ selected, backfill: undefined }, { journal, destination: createMemoryDestination(), now: () => cutoff })
  expect(result.ok).toBe(true)
  expect(attempts).toBe(2)
  expect(journal.events.some((event) => event.eventKind === 'retry_scheduled' && event.errorClass === 'rate_limited')).toBe(true)
})

test.serial('Linear rejects malformed continuation cursors before requesting another page', async () => {
  for (const endCursor of [7, ' ']) {
    let requests = 0
    setFetch(async () => {
      requests++
      return Response.json({ data: { issues: { nodes: [], pageInfo: { hasNextPage: true, endCursor } } } })
    })
    const journal = createMemoryJournal()
    const result = await runIngestion({ selected: selected(), backfill: undefined }, { journal, destination: createMemoryDestination(), now: () => cutoff })
    expect(result.ok).toBe(false)
    expect(result.streams[0]?.error).toContain('no new issue cursor')
    expect(requests).toBe(1)
    expect((await journal.readCheckpoint('linear.issues')).envelope).toBeUndefined()
  }
})
